/* Lot 99: animation-timeline and the ten coordinated animation longhands (generated by scripts/lot99_animgen.py; expectations from scripts/lot99_animmodel.py). */
#include "../../framework/unity.h"
#include <string.h>
#include <stdio.h>
#include "wf_cssprop.h"

static wf_cssanim_t g_a[WF_CSSANIM_MAX];
static char g_t[200];

static int tl(const char *v) {
    memset(g_a, 0x5a, sizeof(g_a));
    return wf_cssanim_long(WF_CSSANIM_L_TIMELINE, v, g_a, WF_CSSANIM_MAX);
}

static const char *tlf(int j) {
    snprintf(g_t, sizeof(g_t), "%d %s", g_a[j].timeline, g_a[j].timeline == WF_CSSANIM_TL_NAMED ? g_a[j].tlname : "-");
    return g_t;
}

static int acoord(const char *const *v, const unsigned char *sh) {
    memset(g_a, 0x5a, sizeof(g_a));
    return wf_cssanim_coord(v, sh, g_a, WF_CSSANIM_MAX);
}

static const char *ez(const wf_cssease_t *e) {
    static char b[64];
    snprintf(b, sizeof(b), "%d %d %d %d %d %d %d", e->kind, e->pos, e->n, e->x1, e->y1, e->x2, e->y2);
    return b;
}

static const char *afield(int k) {
    const wf_cssanim_t *a = &g_a[k];
    snprintf(g_t, sizeof(g_t), "%s %d %d %d %d %d %d %d %s %d %s", a->name[0] ? a->name : "-", a->dur, a->delay,
             a->iters, a->dir, a->fill, a->paused, a->comp, ez(&a->ease), a->timeline,
             a->timeline == WF_CSSANIM_TL_NAMED ? a->tlname : "-");
    return g_t;
}

static void test_l99_timeline_0(void) {
    TEST_ASSERT_EQUAL(3, tl("auto , --scroller , --tl"));
    TEST_ASSERT_EQUAL_STRING("0 -", tlf(0));
    TEST_ASSERT_EQUAL_STRING("2 --scroller", tlf(1));
    TEST_ASSERT_EQUAL_STRING("2 --tl", tlf(2));
    TEST_ASSERT_EQUAL(-1, tl("auto,--t,--"));
    TEST_ASSERT_EQUAL(-1, tl("AUTO,normal"));
    TEST_ASSERT_EQUAL(1, tl("--scroller"));
    TEST_ASSERT_EQUAL_STRING("2 --scroller", tlf(0));
    TEST_ASSERT_EQUAL(4, tl("--_,auto,--_,auto"));
    TEST_ASSERT_EQUAL_STRING("2 --_", tlf(0));
    TEST_ASSERT_EQUAL_STRING("0 -", tlf(1));
    TEST_ASSERT_EQUAL_STRING("2 --_", tlf(2));
    TEST_ASSERT_EQUAL_STRING("0 -", tlf(3));
    TEST_ASSERT_EQUAL(-1, tl("None, --xxxxxxxxxxxxxxxxxxxxxxxxxxxxxx, --xxxxxxxxxxxxxxxxxxxxxxxxxxxxx, --tl, --xxxxxxxxxxxxxxxxxxxxxxxxxxxxx"));
    TEST_ASSERT_EQUAL(-1, tl("scroll(),--_"));
    TEST_ASSERT_EQUAL(4, tl("None,AUTO,--scroller,--_"));
    TEST_ASSERT_EQUAL_STRING("1 -", tlf(0));
    TEST_ASSERT_EQUAL_STRING("0 -", tlf(1));
    TEST_ASSERT_EQUAL_STRING("2 --scroller", tlf(2));
    TEST_ASSERT_EQUAL_STRING("2 --_", tlf(3));
}

